using System;
using System.Globalization;
using System.IO;
using System.Resources;

namespace FFXProjectEditor.Resources;

/// <summary>
/// Jarvis-UI Fase F §F4 (v2.162.4.0) — i18n accessor.
/// <para>
/// Thin static wrapper over a <see cref="ResourceManager"/> backed by <c>Resources/Strings.resx</c>
/// (neutral = en) + the <c>Strings.pt.resx</c> satellite. Exposes one static property per key so it
/// can be bound in XAML via <c>{x:Static res:Strings.KeyName}</c>.
/// </para>
/// <para>
/// The active culture is set once at startup by <see cref="ApplyUiCulture"/> (called from
/// <c>App.OnFrameworkInitializationCompleted</c>). It reads the <c>FFX_UI_LANG</c> env var
/// (<c>pt</c>/<c>en</c>; default = neutral en). Per-value reads go through
/// <see cref="ResourceManager.GetString"/>, which honors <see cref="CultureInfo.CurrentUICulture"/>.
/// </para>
/// <para>
/// Full i18n is infinite work — this is the foundation. To add a new string: append a <c>&lt;data&gt;</c>
/// row to both <c>Strings.resx</c> and <c>Strings.pt.resx</c>, then add a property here that calls
/// <c>S.ResourceManager.GetString(nameof(key))</c>.
/// </para>
/// </summary>
internal static class Strings
{
    public static string U_EventAtelDisassemblyUnavailable => Get(nameof(U_EventAtelDisassemblyUnavailable));
    public static string U_Ai_ComparisonOpcodeSummary => Get(nameof(U_Ai_ComparisonOpcodeSummary));
    public static string U_Ai_UnsignedComparisonOpcodeSummary => Get(nameof(U_Ai_UnsignedComparisonOpcodeSummary));
    public static string U_Md_OpenUpdatePreview => Get(nameof(U_Md_OpenUpdatePreview));
    public static string U_Md_WorkingPreviewHint => Get(nameof(U_Md_WorkingPreviewHint));
    public static string U_Md_WorkingPreviewUpdated => Get(nameof(U_Md_WorkingPreviewUpdated));
    public static string U_Md_WorkingPreviewFailed => Get(nameof(U_Md_WorkingPreviewFailed));
    public static string U_Md_SimulationTab => Get(nameof(U_Md_SimulationTab));
    public static string U_Md_ComparisonTab => Get(nameof(U_Md_ComparisonTab));
    public static string U_Md_ReopenPreview => Get(nameof(U_Md_ReopenPreview));
    public static string U_Ai_AvailableRecipes => Get(nameof(U_Ai_AvailableRecipes));
    public static string U_Ai_IndependentReferenceRequired => Get(nameof(U_Ai_IndependentReferenceRequired));
    public static string U_Ai_InstructionMatchOnly => Get(nameof(U_Ai_InstructionMatchOnly));
    public static string U_Loot_EntryId => Get(nameof(U_Loot_EntryId));
    public static string U_Loot_Reward => Get(nameof(U_Loot_Reward));
    private static readonly ResourceManager _manager =
        new ResourceManager("FFXProjectEditor.Resources.Strings", typeof(Strings).Assembly);

    private const string ConfigFileName = "ui_lang.config";
    private const string EnvLangVar = "FFX_UI_LANG";

    /// <summary>Override for tests; when null, uses %LocalAppData%\FFXProjectEditor.</summary>
    internal static string? ConfigDirectoryOverride { get; set; }

    /// <summary>Directory where the language choice is persisted (per-user, write-safe).</summary>
    public static string ConfigDirectory =>
        ConfigDirectoryOverride ??
        Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "FFXProjectEditor");

    /// <summary>Full path of the persisted language config file.</summary>
    public static string ConfigPath => Path.Combine(ConfigDirectory, ConfigFileName);

    /// <summary>
    /// Applies the UI culture at startup (before any XAML binding reads a Strings property).
    /// Priority: persisted config → <c>FFX_UI_LANG</c> env var → default <c>pt</c>.
    /// </summary>
    public static void ApplyUiCulture()
    {
        ApplyCulture(ResolveLanguage());
    }

    /// <summary>Current UI language code: <c>pt</c>, <c>en</c>, <c>es</c>, <c>fr</c>, <c>de</c>, <c>it</c>, <c>ja</c>, <c>ko</c> or <c>zh</c>.</summary>
    public static string CurrentLanguage
    {
        get
        {
            string name = CultureInfo.CurrentUICulture.Name;
            if (name.StartsWith("pt", StringComparison.OrdinalIgnoreCase)) return "pt";
            if (name.StartsWith("es", StringComparison.OrdinalIgnoreCase)) return "es";
            if (name.StartsWith("fr", StringComparison.OrdinalIgnoreCase)) return "fr";
            if (name.StartsWith("de", StringComparison.OrdinalIgnoreCase)) return "de";
            if (name.StartsWith("it", StringComparison.OrdinalIgnoreCase)) return "it";
            if (name.StartsWith("ja", StringComparison.OrdinalIgnoreCase)) return "ja";
            if (name.StartsWith("ko", StringComparison.OrdinalIgnoreCase)) return "ko";
            if (name.StartsWith("zh", StringComparison.OrdinalIgnoreCase)) return "zh";
            return "en";
        }
    }

    /// <summary>
    /// Persists the language (<c>pt</c>/<c>en</c>/<c>es</c>/<c>fr</c>/<c>de</c>/<c>it</c>/<c>ja</c>/<c>ko</c>/<c>zh</c>) and applies it to the current thread.
    /// The caller restarts the app so XAML <c>{x:Static}</c> bindings re-evaluate.
    /// </summary>
    public static void SetLanguage(string lang)
    {
        string normalized = NormalizeLanguage(lang);
        PersistLanguage(normalized);
        ApplyCulture(normalized);
    }

    /// <summary>Language resolution: persisted config → env var → default pt.</summary>
    public static string ResolveLanguage()
    {
        try
        {
            if (File.Exists(ConfigPath))
            {
                string? persisted = File.ReadAllText(ConfigPath)?.Trim();
                string? norm = NormalizeLanguage(persisted);
                if (norm != "en" || persisted == "en")
                    return norm;
            }
        }
        catch (IOException) { /* unreadable config → fall through */ }
        catch (UnauthorizedAccessException) { /* unreadable config → fall through */ }

        string? env = Environment.GetEnvironmentVariable(EnvLangVar);
        if (!string.IsNullOrEmpty(env))
            return NormalizeLanguage(env);

        return "pt"; // default: the editor UI is predominantly PT
    }

    private static string NormalizeLanguage(string? lang)
    {
        if (string.IsNullOrEmpty(lang))
            return "en";
        if (lang.StartsWith("pt", StringComparison.OrdinalIgnoreCase)) return "pt";
        if (lang.StartsWith("es", StringComparison.OrdinalIgnoreCase)) return "es";
        if (lang.StartsWith("fr", StringComparison.OrdinalIgnoreCase)) return "fr";
        if (lang.StartsWith("de", StringComparison.OrdinalIgnoreCase)) return "de";
        if (lang.StartsWith("it", StringComparison.OrdinalIgnoreCase)) return "it";
        if (lang.StartsWith("ja", StringComparison.OrdinalIgnoreCase)) return "ja";
        if (lang.StartsWith("ko", StringComparison.OrdinalIgnoreCase)) return "ko";
        if (lang.StartsWith("zh", StringComparison.OrdinalIgnoreCase)) return "zh";
        return "en";
    }

    private static void PersistLanguage(string lang)
    {
        try
        {
            Directory.CreateDirectory(ConfigDirectory);
            File.WriteAllText(ConfigPath, lang);
        }
        catch (IOException) { /* persistence is best-effort */ }
        catch (UnauthorizedAccessException) { /* persistence is best-effort */ }
    }

    private static void ApplyCulture(string lang)
    {
        CultureInfo culture = lang switch
        {
            "pt" => new CultureInfo("pt-BR"),
            "es" => new CultureInfo("es-ES"),
            "fr" => new CultureInfo("fr-FR"),
            "de" => new CultureInfo("de-DE"),
            "it" => new CultureInfo("it-IT"),
            "ja" => new CultureInfo("ja-JP"),
            "ko" => new CultureInfo("ko-KR"),
            "zh" => new CultureInfo("zh-CN"),
            _ => CultureInfo.InvariantCulture,
        };
        CultureInfo.DefaultThreadCurrentUICulture = culture;
        CultureInfo.CurrentUICulture = culture;
    }

    /// <summary>Generic localized lookup with optional fallback when the key is missing.</summary>
    public static string Get(string key, string? fallback = null) =>
        _manager.GetString(key, CultureInfo.CurrentUICulture) ?? fallback ?? key;

    /// <summary>ModuleRegistry field lookup. Key pattern: <c>Mod_{id_with_underscores}_{field}</c>.</summary>
    public static string Module(string moduleId, string field, string fallback) =>
        Get($"Mod_{moduleId.Replace('-', '_')}_{field}", fallback);

